INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index, created_at)
VALUES
    ('c0000027-0000-0000-0000-010003000001'::uuid, 'b0000027-0000-0000-0000-000001000003'::uuid, NULL, 'reading', 'fill_blank', 'Pilih vokal pembuka yang tepat untuk kata ''atas'' (うえ):', '{"sentence_template": "[blank] え (atas = ue)", "translation": "Atas (ue)", "options": ["う", "お", "あ", "い"]}'::jsonb, '{"selected": "う"}'::jsonb, 'Kata ''atas'' dalam bahasa Jepang adalah うえ (u-e).', 1, NOW()),
    ('c0000027-0000-0000-0000-010003000002'::uuid, 'b0000027-0000-0000-0000-000001000003'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan pelafalan vokal murni ini:', '{"audio_text": "え", "options": [{"id": "opt_1", "text": "E (vokal)"}, {"id": "opt_2", "text": "I (vokal)"}, {"id": "opt_3", "text": "U (vokal)"}, {"id": "opt_4", "text": "O (vokal)"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'Audio melafalkan vokal え (e).', 2, NOW()),
    ('c0000027-0000-0000-0000-010003000003'::uuid, 'b0000027-0000-0000-0000-000001000003'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kata ''いえ'' (rumah) dari dua vokal utama:', '{"tokens": ["い", "え", "あ", "う"], "target_translation": "Rumah (ie)", "romaji": "Ie"}'::jsonb, '["い", "え"]'::jsonb, 'い (i) + え (e) = いえ (rumah).', 3, NOW()),
    ('c0000027-0000-0000-0000-010003000004'::uuid, 'b0000027-0000-0000-0000-000001000003'::uuid, NULL, 'reading', 'fill_blank', 'Kontras visual: huruf manakah yang memiliki titik di sudut kanan atas?', '{"sentence_template": "Huruf vokal ''o'' adalah [blank]", "translation": "Vokal O", "options": ["お", "あ", "む", "め"]}'::jsonb, '{"selected": "お"}'::jsonb, 'Huruf お memiliki satu titik goresan di kanan atas; あ tidak memiliki titik.', 4, NOW()),
    ('c0000027-0000-0000-0000-010003000005'::uuid, 'b0000027-0000-0000-0000-000001000003'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan kata dari deret K ini:', '{"audio_text": "きく", "options": [{"id": "opt_1", "text": "Mendengar / Krisan (kiku)"}, {"id": "opt_2", "text": "Musim gugur (aki)"}, {"id": "opt_3", "text": "Wajah (kao)"}, {"id": "opt_4", "text": "Stasiun (eki)"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'き (ki) + く (ku) = きく (kiku).', 5, NOW()),
    ('c0000027-0000-0000-0000-010003000006'::uuid, 'b0000027-0000-0000-0000-000001000003'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kata ''うえ'' (atas) dengan vokal yang benar:', '{"tokens": ["う", "え", "い", "お"], "target_translation": "Atas (ue)", "romaji": "Ue"}'::jsonb, '["う", "え"]'::jsonb, 'う (u) + え (e) = うえ (atas).', 6, NOW()),
    ('c0000027-0000-0000-0000-010003000007'::uuid, 'b0000027-0000-0000-0000-000001000003'::uuid, NULL, 'speaking', 'speaking_repeat', 'Lafalkan dengan intonasi jelas kata ''いえ'' (rumah):', '{"display_text": "いえ", "romaji": "ie (rumah)", "audio_text": "いえ"}'::jsonb, '{"expected_transcript": "いえ"}'::jsonb, 'Ucapkan i-e dengan nada datar alami.', 7, NOW()),
    ('c0000027-0000-0000-0000-010003000008'::uuid, 'b0000027-0000-0000-0000-000001000003'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kata ''musim gugur'' (aki):', '{"sentence_template": "あ [blank] (musim gugur)", "translation": "Musim gugur (aki)", "options": ["き", "か", "く", "け"]}'::jsonb, '{"selected": "き"}'::jsonb, 'あ (a) + き (ki) = あき (musim gugur).', 8, NOW()),
    ('c0000027-0000-0000-0000-010004000001'::uuid, 'b0000027-0000-0000-0000-000001000004'::uuid, NULL, 'reading', 'fill_blank', 'Pilih huruf untuk kata ''kolam'' (ike):', '{"sentence_template": "い [blank] (kolam = ike)", "translation": "Kolam (ike)", "options": ["け", "き", "こ", "か"]}'::jsonb, '{"selected": "け"}'::jsonb, 'い (i) + け (ke) = いけ (kolam).', 1, NOW()),
    ('c0000027-0000-0000-0000-010004000002'::uuid, 'b0000027-0000-0000-0000-000001000004'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan kata penunjuk posisi ini:', '{"audio_text": "ここ", "options": [{"id": "opt_1", "text": "Di sini (koko)"}, {"id": "opt_2", "text": "Wajah (kao)"}, {"id": "opt_3", "text": "Kolam (ike)"}, {"id": "opt_4", "text": "Biru (aoi)"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'こ (ko) + こ (ko) = ここ (di sini).', 2, NOW()),
    ('c0000027-0000-0000-0000-010004000003'::uuid, 'b0000027-0000-0000-0000-000001000004'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kata ''かお'' (wajah) dari huruf K dan vokal:', '{"tokens": ["か", "お", "あ", "こ"], "target_translation": "Wajah (kao)", "romaji": "Kao"}'::jsonb, '["か", "お"]'::jsonb, 'か (ka) + お (o) = かお (wajah).', 3, NOW()),
    ('c0000027-0000-0000-0000-010004000004'::uuid, 'b0000027-0000-0000-0000-000001000004'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kata yang berarti ''stasiun'' (eki):', '{"sentence_template": "え [blank] (stasiun)", "translation": "Stasiun (eki)", "options": ["き", "く", "け", "こ"]}'::jsonb, '{"selected": "き"}'::jsonb, 'え (e) + き (ki) = えき (stasiun kereta).', 4, NOW()),
    ('c0000027-0000-0000-0000-010004000005'::uuid, 'b0000027-0000-0000-0000-000001000004'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan sebutan warna ini:', '{"audio_text": "あかい", "options": [{"id": "opt_1", "text": "Merah (akai)"}, {"id": "opt_2", "text": "Biru (aoi)"}, {"id": "opt_3", "text": "Pagi (asa)"}, {"id": "opt_4", "text": "Rumah (ie)"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'あ (a) + か (ka) + い (i) = あかい (merah).', 5, NOW()),
    ('c0000027-0000-0000-0000-010004000006'::uuid, 'b0000027-0000-0000-0000-000001000004'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kata ''あき'' (musim gugur):', '{"tokens": ["あ", "き", "い", "か"], "target_translation": "Musim gugur (aki)", "romaji": "Aki"}'::jsonb, '["あ", "き"]'::jsonb, 'あ (a) + き (ki) = あき (musim gugur).', 6, NOW()),
    ('c0000027-0000-0000-0000-010004000007'::uuid, 'b0000027-0000-0000-0000-000001000004'::uuid, NULL, 'speaking', 'speaking_repeat', 'Tirukan ucapan penunjuk tempat ''ここ'' (koko):', '{"display_text": "ここ", "romaji": "koko (di sini)", "audio_text": "ここ"}'::jsonb, '{"expected_transcript": "ここ"}'::jsonb, 'Ucapkan ko-ko dengan vokal pendek.', 7, NOW()),
    ('c0000027-0000-0000-0000-010004000008'::uuid, 'b0000027-0000-0000-0000-000001000004'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi warna ''biru'' (aoi):', '{"sentence_template": "あ [blank] い (biru)", "translation": "Biru (aoi)", "options": ["お", "え", "う", "か"]}'::jsonb, '{"selected": "お"}'::jsonb, 'あ (a) + お (o) + い (i) = あおい (biru).', 8, NOW()),
    ('c0000027-0000-0000-0000-010007000001'::uuid, 'b0000027-0000-0000-0000-000001000007'::uuid, NULL, 'reading', 'fill_blank', 'Ujian 1: Huruf manakah yang dibaca ''ku'' pada deret K?', '{"sentence_template": "Pilihan huruf ''ku'': [blank]", "translation": "Huruf KU", "options": ["く", "け", "こ", "か"]}'::jsonb, '{"selected": "く"}'::jsonb, 'Bentuk paruh burung adalah く (ku).', 1, NOW()),
    ('c0000027-0000-0000-0000-010007000002'::uuid, 'b0000027-0000-0000-0000-000001000007'::uuid, NULL, 'listening', 'listening_choice', 'Ujian 2: Dengarkan kata berikut dan pilih artinya:', '{"audio_text": "いえ", "options": [{"id": "opt_1", "text": "Rumah"}, {"id": "opt_2", "text": "Atas"}, {"id": "opt_3", "text": "Wajah"}, {"id": "opt_4", "text": "Kolam"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'いえ artinya rumah.', 2, NOW()),
    ('c0000027-0000-0000-0000-010007000003'::uuid, 'b0000027-0000-0000-0000-000001000007'::uuid, NULL, 'writing', 'sentence_builder', 'Ujian 3: Susun kata ''あおい'' (biru):', '{"tokens": ["あ", "お", "い", "え"], "target_translation": "Biru (aoi)", "romaji": "Aoi"}'::jsonb, '["あ", "お", "い"]'::jsonb, 'あ + お + い = あおい.', 3, NOW()),
    ('c0000027-0000-0000-0000-010007000004'::uuid, 'b0000027-0000-0000-0000-000001000007'::uuid, NULL, 'reading', 'fill_blank', 'Ujian 4: Manakah kata yang berarti ''stasiun''?', '{"sentence_template": "[blank] (stasiun kereta)", "translation": "Stasiun", "options": ["えき", "いけ", "あき", "かお"]}'::jsonb, '{"selected": "えき"}'::jsonb, 'えき (eki) berarti stasiun.', 4, NOW()),
    ('c0000027-0000-0000-0000-010007000005'::uuid, 'b0000027-0000-0000-0000-000001000007'::uuid, NULL, 'listening', 'listening_choice', 'Ujian 5: Dengarkan huruf tunggal ini:', '{"audio_text": "か", "options": [{"id": "opt_1", "text": "Ka"}, {"id": "opt_2", "text": "Ko"}, {"id": "opt_3", "text": "Ki"}, {"id": "opt_4", "text": "Ku"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'Audio melafalkan huruf か (ka).', 5, NOW()),
    ('c0000027-0000-0000-0000-010007000006'::uuid, 'b0000027-0000-0000-0000-000001000007'::uuid, NULL, 'writing', 'sentence_builder', 'Ujian 6: Susun kata ''うえ'' (atas):', '{"tokens": ["う", "え", "お", "い"], "target_translation": "Atas (ue)", "romaji": "Ue"}'::jsonb, '["う", "え"]'::jsonb, 'う + え = うえ (atas).', 6, NOW()),
    ('c0000027-0000-0000-0000-010007000007'::uuid, 'b0000027-0000-0000-0000-000001000007'::uuid, NULL, 'reading', 'fill_blank', 'Ujian 7: Kata ''kolam'' ditulis:', '{"sentence_template": "[blank] (kolam)", "translation": "Kolam", "options": ["いけ", "えき", "あき", "ここ"]}'::jsonb, '{"selected": "いけ"}'::jsonb, 'いけ (ike) berarti kolam.', 7, NOW()),
