    ('c0000027-0000-0000-0000-020003000005'::uuid, 'b0000027-0000-0000-0000-000002000003'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan kata makanan khas ini:', '{"audio_text": "すし", "options": [{"id": "opt_1", "text": "Sushi"}, {"id": "opt_2", "text": "Sepatu (kutsu)"}, {"id": "opt_3", "text": "Pagi (asa)"}, {"id": "opt_4", "text": "Kursi (isu)"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'す (su) + し (shi) = すし (sushi).', 5, NOW()),
