    ('c0000027-0000-0000-0000-020004000001'::uuid, 'b0000027-0000-0000-0000-000002000004'::uuid, NULL, 'reading', 'fill_blank', 'Pilih huruf dengan simpul ganda untuk ''anjing'' (inu):', '{"sentence_template": "い [blank] (anjing = inu)", "translation": "Anjing (inu)", "options": ["ぬ", "ね", "の", "な"]}'::jsonb, '{"selected": "ぬ"}'::jsonb, 'い (i) + ぬ (nu) = いぬ (anjing).', 1, NOW()),
