    ('c0000027-0000-0000-0000-290007000010'::uuid, 'b0000027-0000-0000-0000-000029000007'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ujian 10: Lafalkan dengan jelas ''日本 へ 行って、桜 を 見たい です'':', '{"display_text": "日本 へ 行って、桜 を 見たい です", "romaji": "Nihon e itte, sakura o mitai desu", "audio_text": "日本 へ 行って、桜 を 見たい です"}'::jsonb, '{"expected_transcript": "日本 へ 行って、桜 を 見たい です"}'::jsonb, 'Lafalkan Nihon e itte, sakura o mitai desu.', 10, NOW()),
    ('c0000027-0000-0000-0000-300003000001'::uuid, 'b0000027-0000-0000-0000-000030000003'::uuid, NULL, 'reading', 'fill_blank', 'Kontras partikel tempat: Keberadaan benda mati di tempat memakai [blank], sedangkan aksi aktif memakai で:', '{"sentence_template": "つくえ [blank] ほん が あります", "translation": "Partikel NI", "options": ["に", "で", "を", "へ"]}'::jsonb, '{"selected": "に"}'::jsonb, 'Tempat keberadaan statis memakai に (tsukue ni hon ga arimasu).', 1, NOW()),
    ('c0000027-0000-0000-0000-300003000002'::uuid, 'b0000027-0000-0000-0000-000030000003'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan jebakan partikel alat vs tempat ini:', '{"audio_text": "にほんご で レポート を かきました", "options": [{"id": "opt_1", "text": "Menulis laporan dalam bahasa Jepang (sarana bahasa)"}, {"id": "opt_2", "text": "Menulis laporan di Jepang (lokasi)"}, {"id": "opt_3", "text": "Membaca laporan tentang Jepang"}, {"id": "opt_4", "text": "Mengirim laporan ke Jepang"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'にほんご で = dengan/dalam bahasa Jepang (sarana/alat).', 2, NOW()),
    ('c0000027-0000-0000-0000-300003000003'::uuid, 'b0000027-0000-0000-0000-000030000003'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kalimat multi-partikel ''毎日 ７時に 起きて 電車で 会社へ 行きます'':', '{"tokens": ["毎日７時に起きて", "電車で", "会社へ行きます"], "target_translation": "Bangun jam 7 naik kereta ke kantor", "romaji": "Mainichi shichiji ni okite densha de kaisha e ikimasu"}'::jsonb, '["毎日７時に起きて", "電車で", "会社へ行きます"]'::jsonb, 'Mainichi shichiji ni okite densha de kaisha e ikimasu.', 3, NOW()),
    ('c0000027-0000-0000-0000-300003000004'::uuid, 'b0000027-0000-0000-0000-000030000003'::uuid, NULL, 'reading', 'fill_blank', 'Kontras partikel penanda subjek: Subjek topik umum memakai は, sedangkan subjek pengenal spesifik/fokus memakai [blank]:', '{"sentence_template": "だれ [blank] きましたか (Siapa yang datang?)", "translation": "Partikel GA", "options": ["が", "は", "を", "に"]}'::jsonb, '{"selected": "が"}'::jsonb, 'Kata tanya penanya subjek wajib menggunakan が (だれが きましたか).', 4, NOW()),
    ('c0000027-0000-0000-0000-300003000005'::uuid, 'b0000027-0000-0000-0000-000030000003'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan perbedaan arah vs tempat tinggal:', '{"audio_text": "とうきょう に すんで います", "options": [{"id": "opt_1", "text": "Tinggal menetap di Tokyo"}, {"id": "opt_2", "text": "Sedang pergi ke Tokyo"}, {"id": "opt_3", "text": "Berasal dari Tokyo"}, {"id": "opt_4", "text": "Bekerja di Tokyo"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'とうきょう に すんで います (Status tempat tinggal menetap).', 5, NOW()),
    ('c0000027-0000-0000-0000-300003000006'::uuid, 'b0000027-0000-0000-0000-000030000003'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kontras ''パンは 食べますが、ご飯は 食べません'' (Roti makan, tapi nasi tidak):', '{"tokens": ["パンは食べますが", "ご飯は", "食べません"], "target_translation": "Makan roti tapi tidak makan nasi", "romaji": "Pan wa tabemasu ga, gohan wa tabemasen"}'::jsonb, '["パンは食べますが", "ご飯は", "食べません"]'::jsonb, 'Pan wa tabemasu ga, gohan wa tabemasen.', 6, NOW()),
    ('c0000027-0000-0000-0000-300003000007'::uuid, 'b0000027-0000-0000-0000-000030000003'::uuid, NULL, 'speaking', 'speaking_repeat', 'Lafalkan kalimat multi-partikel ''図書館 で 友だち と 勉強します'':', '{"display_text": "図書館 で 友だち と 勉強します", "romaji": "toshokan de tomodachi to benkyoushimasu", "audio_text": "図書館 で 友だち と 勉強します"}'::jsonb, '{"expected_transcript": "図書館 で 友だち と 勉強します"}'::jsonb, 'Lafalkan toshokan de tomodachi to benkyoushimasu.', 7, NOW()),
    ('c0000027-0000-0000-0000-300003000008'::uuid, 'b0000027-0000-0000-0000-000030000003'::uuid, NULL, 'reading', 'fill_blank', 'Waktu yang tidak menggunakan angka (seperti きょう, あした, まいにち) [blank] partikel に:', '{"sentence_template": "あした [blank] 行きます (Besok akan pergi)", "translation": "Tanpa partikel", "options": ["tidak memakai", "memakai", "wajib", "boleh"]}'::jsonb, '{"selected": "tidak memakai"}'::jsonb, 'Keterangan waktu relatif tanpa angka tidak memakai partikel に (あした 行きます).', 8, NOW())
INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index, created_at)
VALUES
    ('c0000027-0000-0000-0000-300004000001'::uuid, 'b0000027-0000-0000-0000-000030000004'::uuid, NULL, 'reading', 'fill_blank', 'Papan pengumuman di pintu toko: 定休日 (teikyuubi) berarti:', '{"sentence_template": "Pengumuman 定休日: [blank]", "translation": "Hari libur rutin", "options": ["hari libur rutin toko", "buka 24 jam", "sedang diskon", "pintu masuk"]}'::jsonb, '{"selected": "hari libur rutin toko"}'::jsonb, '定休日 (teikyuubi) = hari libur rutin mingguan toko.', 1, NOW()),
    ('c0000027-0000-0000-0000-300004000002'::uuid, 'b0000027-0000-0000-0000-000030000004'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman di stasiun kereta ini:', '{"audio_text": "まもなく にばんせん に 電車 が まいります", "options": [{"id": "opt_1", "text": "Sebentar lagi kereta akan tiba di jalur 2"}, {"id": "opt_2", "text": "Kereta jalur 2 telah berangkat"}, {"id": "opt_3", "text": "Jalur 2 sedang diperbaiki"}, {"id": "opt_4", "text": "Pintu keluar ada di jalur 2"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'まもなく にばんせん に 電車 が まいります (Kereta segera tiba di peron 2).', 2, NOW()),
    ('c0000027-0000-0000-0000-300004000003'::uuid, 'b0000027-0000-0000-0000-000030000004'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kata ''ていきゅうび'' (hari libur rutin):', '{"tokens": ["定", "休", "日"], "target_translation": "Hari libur rutin", "romaji": "Teikyuubi"}'::jsonb, '["定", "休", "日"]'::jsonb, '定休日.', 3, NOW()),
    ('c0000027-0000-0000-0000-300004000004'::uuid, 'b0000027-0000-0000-0000-000030000004'::uuid, NULL, 'reading', 'fill_blank', 'Tiket masuk museum: ９：００～１７：００ (入館は１６：３0まで) berarti jam masuk terakhir adalah:', '{"sentence_template": "Jam masuk terakhir: [blank]", "translation": "16.30", "options": ["16.30", "17.00", "09.00", "16.00"]}'::jsonb, '{"selected": "16.30"}'::jsonb, '入館は１６：３０まで (Batas masuk paling lambat 16.30).', 4, NOW()),
    ('c0000027-0000-0000-0000-300004000005'::uuid, 'b0000027-0000-0000-0000-000030000004'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan petunjuk mesin tiket otomatis:', '{"audio_text": "おつり と きっぷ を おとり ください", "options": [{"id": "opt_1", "text": "Silakan ambil tiket dan uang kembalian Anda"}, {"id": "opt_2", "text": "Masukkan uang Anda"}, {"id": "opt_3", "text": "Pilihlah stasiun tujuan"}, {"id": "opt_4", "text": "Tiket Anda salah"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'おつり (kembalian) と きっぷ (tiket) を おとり ください.', 5, NOW()),
    ('c0000027-0000-0000-0000-300004000006'::uuid, 'b0000027-0000-0000-0000-000030000004'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kalimat instruksi ''切符を お取り ください'' (Silakan ambil tiket):', '{"tokens": ["切符を", "お取り", "ください"], "target_translation": "Silakan ambil tiket", "romaji": "Kippu o otori kudasai"}'::jsonb, '["切符を", "お取り", "ください"]'::jsonb, 'Kippu o otori kudasai.', 6, NOW()),
    ('c0000027-0000-0000-0000-300004000007'::uuid, 'b0000027-0000-0000-0000-000030000004'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ucapkan konfirmasi informasi tiket ''とうきょう まで いちまい おねがいします'':', '{"display_text": "東京 まで 一枚 おねがいします", "romaji": "Toukyou made ichimai onegaishimasu", "audio_text": "東京 まで 一枚 おねがいします"}'::jsonb, '{"expected_transcript": "東京 まで 一枚 おねがいします"}'::jsonb, 'Lafalkan Toukyou made ichimai onegaishimasu.', 7, NOW()),
    ('c0000027-0000-0000-0000-300004000008'::uuid, 'b0000027-0000-0000-0000-000030000004'::uuid, NULL, 'reading', 'fill_blank', 'Pemberitahuan darurat ''Dilarang masuk'' di pintu gerbang ditulis:', '{"sentence_template": "Tanda: 立入禁止 (Tachiiri kinshi) = [blank]", "translation": "Dilarang masuk", "options": ["dilarang masuk", "dilarang parkir", "jalan satu arah", "awas basah"]}'::jsonb, '{"selected": "dilarang masuk"}'::jsonb, '立入禁止 (tachiiri kinshi) = dilarang masuk.', 8, NOW()),
    ('c0000027-0000-0000-0000-300006000001'::uuid, 'b0000027-0000-0000-0000-000030000006'::uuid, NULL, 'reading', 'fill_blank', 'Pertanyaan pembuka wawancara: ''Ceritakan perkenalan diri Anda secara singkat'':', '{"sentence_template": "じこしょうかい を [blank] ください", "translation": "Onegaishimasu / shite", "options": ["おねがいします", "みせて", "たべて", "きいて"]}'::jsonb, '{"selected": "おねがいします"}'::jsonb, '自己紹介 を おねがいします (Silakan perkenalkan diri Anda).', 1, NOW()),
    ('c0000027-0000-0000-0000-300006000002'::uuid, 'b0000027-0000-0000-0000-000030000006'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan pertanyaan pewawancara ini:', '{"audio_text": "どうして 日本語 を 勉強して いますか", "options": [{"id": "opt_1", "text": "Mengapa Anda belajar bahasa Jepang?"}, {"id": "opt_2", "text": "Di mana Anda belajar bahasa Jepang?"}, {"id": "opt_3", "text": "Sejak kapan belajar bahasa Jepang?"}, {"id": "opt_4", "text": "Apakah bahasa Jepang susah?"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'どうして (mengapa) 日本語 を 勉強して いますか.', 2, NOW()),
    ('c0000027-0000-0000-0000-300006000003'::uuid, 'b0000027-0000-0000-0000-000030000006'::uuid, NULL, 'writing', 'sentence_builder', 'Susun jawaban alasan ''日本で 働きたい から です'' (Karena ingin bekerja di Jepang):', '{"tokens": ["日本で", "働きたい", "からです"], "target_translation": "Karena ingin kerja di Jepang", "romaji": "Nihon de hatarakitai kara desu"}'::jsonb, '["日本で", "働きたい", "からです"]'::jsonb, 'Nihon de hatarakitai kara desu.', 3, NOW()),
    ('c0000027-0000-0000-0000-300006000004'::uuid, 'b0000027-0000-0000-0000-000030000006'::uuid, NULL, 'reading', 'fill_blank', 'Menanyakan durasi belajar ''Sudah berapa lama belajar bahasa Jepang?'':', '{"sentence_template": "どのくらい [blank] 勉強しましたか", "translation": "Jikan / kikan", "options": ["日本語を", "日本へ", "日本で", "日本から"]}'::jsonb, '{"selected": "日本語を"}'::jsonb, 'どのくらい 日本語を 勉強しましたか.', 4, NOW()),
    ('c0000027-0000-0000-0000-300006000005'::uuid, 'b0000027-0000-0000-0000-000030000006'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan respon pengalaman kerja:', '{"audio_text": "一年間 かいしゃ で はたらいた こと が あります", "options": [{"id": "opt_1", "text": "Pernah bekerja di perusahaan selama 1 tahun"}, {"id": "opt_2", "text": "Ingin bekerja selama 1 tahun"}, {"id": "opt_3", "text": "Baru 1 bulan bekerja"}, {"id": "opt_4", "text": "Tidak pernah bekerja"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '一年間 (selama 1 tahun) はたらいた ことが あります.', 5, NOW()),
    ('c0000027-0000-0000-0000-300006000006'::uuid, 'b0000027-0000-0000-0000-000030000006'::uuid, NULL, 'writing', 'sentence_builder', 'Susun komitmen ''一生懸命 頑張ります'' (Saya akan berusaha sekuat tenaga):', '{"tokens": ["一生懸命", "頑張ります"], "target_translation": "Akan berjuang keras", "romaji": "Isshoukenmei gambarimasu"}'::jsonb, '["一生懸命", "頑張ります"]'::jsonb, 'Isshoukenmei gambarimasu.', 6, NOW()),
    ('c0000027-0000-0000-0000-300006000007'::uuid, 'b0000027-0000-0000-0000-000030000006'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ucapkan komitmen wawancara ''一生懸命 頑張ります ので、よろしく お願いします'':', '{"display_text": "一生懸命 頑張ります ので、よろしく お願いします", "romaji": "isshoukenmei gambarimasu node, yoroshiku onegaishimasu", "audio_text": "一生懸命 頑張ります ので、よろしく お願いします"}'::jsonb, '{"expected_transcript": "一生懸命 頑張ります ので、よろしく お願いします"}'::jsonb, 'Lafalkan komitmen dengan sungguh-sungguh dan percaya diri.', 7, NOW()),
    ('c0000027-0000-0000-0000-300006000008'::uuid, 'b0000027-0000-0000-0000-000030000006'::uuid, NULL, 'reading', 'fill_blank', 'Salam penutup wawancara formal:', '{"sentence_template": "きょう は ありがとう [blank]", "translation": "Gozaimashita", "options": ["ございました", "ございます", "です", "でした"]}'::jsonb, '{"selected": "ございました"}'::jsonb, 'Terima kasih atas wawancara hari ini = ありがとうございました.', 8, NOW()),
    ('c0000027-0000-0000-0000-010001000006'::uuid, 'b0000002-0000-0000-0000-000000000002'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan vokal berurutan ini:', '{"audio_text": "あいうえお", "options": [{"id": "opt_1", "text": "Urutan 5 vokal (A-I-U-E-O)"}, {"id": "opt_2", "text": "Deret K"}, {"id": "opt_3", "text": "Deret S"}, {"id": "opt_4", "text": "Kata salam"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'Audio melafalkan urutan 5 vokal standar: a-i-u-e-o.', 6, NOW()),
    ('c0000027-0000-0000-0000-010001000007'::uuid, 'b0000002-0000-0000-0000-000000000002'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kata ''あい'' (cinta/kasih) dari vokal dasar:', '{"tokens": ["あ", "い", "う", "え"], "target_translation": "Cinta / kasih (ai)", "romaji": "Ai"}'::jsonb, '["あ", "い"]'::jsonb, 'あ (a) + い (i) = あい (ai).', 7, NOW()),
    ('c0000027-0000-0000-0000-010001000008'::uuid, 'b0000002-0000-0000-0000-000000000002'::uuid, NULL, 'speaking', 'speaking_repeat', 'Lafalkan 5 vokal utama bahasa Jepang dengan runtut:', '{"display_text": "あいうえお", "romaji": "a-i-u-e-o", "audio_text": "あいうえお"}'::jsonb, '{"expected_transcript": "あいうえお"}'::jsonb, 'Ucapkan lima vokal dasar dengan tempo stabil.', 8, NOW()),
    ('c0000027-0000-0000-0000-010002000004'::uuid, 'b0000026-0000-0000-0000-000000000102'::uuid, NULL, 'reading', 'fill_blank', 'Pilih huruf untuk kata ''kaki'' (buah kesemek):', '{"sentence_template": "か [blank] (buah kesemek = kaki)", "translation": "Kesemek (kaki)", "options": ["き", "く", "け", "こ"]}'::jsonb, '{"selected": "き"}'::jsonb, 'か (ka) + き (ki) = かき (buah kesemek).', 4, NOW()),
    ('c0000027-0000-0000-0000-010002000005'::uuid, 'b0000026-0000-0000-0000-000000000102'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan kata dari deret K ini:', '{"audio_text": "こえ", "options": [{"id": "opt_1", "text": "Suara (koe)"}, {"id": "opt_2", "text": "Kolam (ike)"}, {"id": "opt_3", "text": "Rumah (ie)"}, {"id": "opt_4", "text": "Di sini (koko)"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'こ (ko) + え (e) = こえ (suara).', 5, NOW()),
    ('c0000027-0000-0000-0000-010002000006'::uuid, 'b0000026-0000-0000-0000-000000000102'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kata ''こえ'' (suara) dari deret K dan vokal:', '{"tokens": ["こ", "え", "か", "い"], "target_translation": "Suara (koe)", "romaji": "Koe"}'::jsonb, '["こ", "え"]'::jsonb, 'こ + え = こえ (suara).', 6, NOW()),
    ('c0000027-0000-0000-0000-010002000007'::uuid, 'b0000026-0000-0000-0000-000000000102'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ucapkan kata ''かお'' (wajah):', '{"display_text": "かお", "romaji": "kao (wajah)", "audio_text": "かお"}'::jsonb, '{"expected_transcript": "かお"}'::jsonb, 'Lafalkan ka-o.', 7, NOW()),
    ('c0000027-0000-0000-0000-010002000008'::uuid, 'b0000026-0000-0000-0000-000000000102'::uuid, NULL, 'reading', 'fill_blank', 'Kata ''kue'' dalam bahasa Jepang adalah:', '{"sentence_template": "お [blank] し (kue)", "translation": "Kue (okashi)", "options": ["か", "き", "く", "け"]}'::jsonb, '{"selected": "か"}'::jsonb, 'お + か + し = おかし (okashi).', 8, NOW()),
    ('c0000027-0000-0000-0000-010005000006'::uuid, 'b0000001-0000-0000-0000-000000000008'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi sapaan pendek ''iya/benar'':', '{"sentence_template": "[blank] え (iya = ee)", "translation": "Iya (ee)", "options": ["え", "あ", "い", "お"]}'::jsonb, '{"selected": "え"}'::jsonb, 'ええ (ee) digunakan dalam percakapan kasual untuk ''iya''.', 6, NOW()),
    ('c0000027-0000-0000-0000-010005000007'::uuid, 'b0000001-0000-0000-0000-000000000008'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kata ''いいえ'' (tidak/bukan):', '{"tokens": ["い", "い", "え", "あ"], "target_translation": "Tidak / bukan (iie)", "romaji": "Iie"}'::jsonb, '["い", "い", "え"]'::jsonb, 'い + い + え = いいえ (iie).', 7, NOW()),
    ('c0000027-0000-0000-0000-010005000008'::uuid, 'b0000001-0000-0000-0000-000000000008'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ucapkan penegasan sopan ''いいえ'' (tidak):', '{"display_text": "いいえ", "romaji": "iie", "audio_text": "いいえ"}'::jsonb, '{"expected_transcript": "いいえ"}'::jsonb, 'Lafalkan i-i-e dengan intonasi sopan.', 8, NOW()),
    ('c0000027-0000-0000-0000-010006000005'::uuid, 'b0000026-0000-0000-0000-000000000104'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kata seru/sapaan pendek:', '{"sentence_template": "お [blank] (halo/wah)", "translation": "Sapaan pendek", "options": ["お", "あ", "う", "え"]}'::jsonb, '{"selected": "お"}'::jsonb, 'おお (oo) sering dipakai sebagai seruan sapaan.', 5, NOW()),
    ('c0000027-0000-0000-0000-010006000006'::uuid, 'b0000026-0000-0000-0000-000000000104'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan gabungan kata pendek ini:', '{"audio_text": "あかい いえ", "options": [{"id": "opt_1", "text": "Rumah merah"}, {"id": "opt_2", "text": "Rumah biru"}, {"id": "opt_3", "text": "Musim gugur"}, {"id": "opt_4", "text": "Wajah putih"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'あかい (merah) + いえ (rumah) = rumah merah.', 6, NOW()),
