    ('c0000027-0000-0000-0000-270005000008'::uuid, 'b0000026-0000-0000-0000-000000002703'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat ketika sakit minum obat:', '{"phrase": "頭が痛いとき、この薬を飲みます。", "romaji": "Atama ga itai toki, kono kusuri o nomimasu.", "translation": "Ketika kepala sakit, saya minum obat ini."}'::jsonb, '{"exact_match": "頭が痛いとき、この薬を飲みます。"}'::jsonb, 'Kata sifat-i + とき menyatakan "pada saat/ketika kondisi tersebut".', 8, NOW()),
    ('c0000027-0000-0000-0000-270006000005'::uuid, 'b0000026-0000-0000-0000-000000002704'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Saat anak-anak, tinggal di Osaka'':', '{"sentence_template": "こどもの [blank]、大阪 に 住んでいました", "translation": "Toki", "options": ["とき", "まえに", "あとで", "から"]}'::jsonb, '{"selected": "とき"}'::jsonb, 'こどもの とき (saat anak-anak).', 5, NOW()),
    ('c0000027-0000-0000-0000-270006000006'::uuid, 'b0000026-0000-0000-0000-000000002704'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan situasi waktu muda ini:', '{"audio_text": "わかい とき、よく りょこう を しました", "options": [{"id": "opt_1", "text": "Saat masih muda, sering bepergian wisata"}, {"id": "opt_2", "text": "Saat muda tidak pernah liburan"}, {"id": "opt_3", "text": "Ingin bepergian sekarang"}, {"id": "opt_4", "text": "Jepang sangat indah"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'わかい とき (ketika masih muda) よく りょこう を しました.', 6, NOW()),
