    ('c0000027-0000-0000-0000-270006000008'::uuid, 'b0000026-0000-0000-0000-000000002704'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ucapkan hobi saat luang ''暇な とき、本 を 読みます'':', '{"display_text": "暇な とき、本 を 読みます", "romaji": "himana toki, hon o yomimasu", "audio_text": "暇な とき、本 を 読みます"}'::jsonb, '{"expected_transcript": "暇な とき、本 を 読みます"}'::jsonb, 'Lafalkan himana toki, hon o yomimasu.', 8, NOW()),
