    ('c0000027-0000-0000-0000-280001000006'::uuid, 'b0000026-0000-0000-0000-000000002801'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ucapkan obrolan kasual ''これ おいしい ね'':', '{"display_text": "これ おいしい ね", "romaji": "kore oishii ne", "audio_text": "これ おいしい ね"}'::jsonb, '{"expected_transcript": "これ おいしい ね"}'::jsonb, 'Lafalkan kore oishii ne secara akrab.', 6, NOW()),
