    ('c0000027-0000-0000-0000-280002000006'::uuid, 'b0000026-0000-0000-0000-000000002802'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan opini pembicara mengenai harga barang:', '{"audio_text": "日本は物価が高いと思います。", "options": [{"id": "opt_1", "text": "Saya rasa harga barang di Jepang mahal."}, {"id": "opt_2", "text": "Saya rasa Jepang sangat aman."}, {"id": "opt_3", "text": "Saya rasa orang Jepang sangat sibuk."}, {"id": "opt_4", "text": "Harga barang di toko itu murah."}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, '～と思います (to omoimasu) menyatakan pendapat/opini pribadi.', 6, NOW()),
    ('c0000027-0000-0000-0000-280002000007'::uuid, 'b0000026-0000-0000-0000-000000002802'::uuid, NULL, 'reading', 'fill_blank', 'Pilih kalimat kutipan langsung perkataan dokter:', '{"sentence_template": "医者は「明日 [blank] ください」と言いました。", "translation": "Dokter berkata \"Besok tolong istirahat.\"", "options": ["休んで", "休み", "休む", "休んだ"]}'::jsonb, '{"selected": "休んで"}'::jsonb, 'Dalam tanda kurung siku 「」 dapat berupa kalimat perintah/sopan apa adanya.', 7, NOW()),
    ('c0000027-0000-0000-0000-280002000008'::uuid, 'b0000026-0000-0000-0000-000000002802'::uuid, NULL, 'speaking', 'speaking_repeat', 'Ucapkan opini mengenai cuaca esok hari:', '{"phrase": "明日は雨が降ると思います。", "romaji": "Ashita wa ame ga furu to omoimasu.", "translation": "Saya rasa besok akan turun hujan."}'::jsonb, '{"exact_match": "明日は雨が降ると思います。"}'::jsonb, 'Sebelum と思います gunakan bentuk biasa kasual (furu).', 8, NOW()),
    ('c0000027-0000-0000-0000-280005000004'::uuid, 'b0000026-0000-0000-0000-000000002803'::uuid, NULL, 'reading', 'fill_blank', 'Lengkapi kalimat opini ''Saya rasa Tanaka tidak akan datang'':', '{"sentence_template": "たなかさん は こない [blank] おもいます", "translation": "To", "options": ["と", "を", "に", "が"]}'::jsonb, '{"selected": "と"}'::jsonb, 'こない と おもいます.', 4, NOW()),
    ('c0000027-0000-0000-0000-280005000005'::uuid, 'b0000026-0000-0000-0000-000000002803'::uuid, NULL, 'writing', 'sentence_builder', 'Susun kalimat ''来ない と 思います'':', '{"tokens": ["来ないと", "思います"], "target_translation": "Saya rasa tidak datang", "romaji": "Konai to omoimasu"}'::jsonb, '["来ないと", "思います"]'::jsonb, 'Konai to omoimasu.', 5, NOW()),
    ('c0000027-0000-0000-0000-280005000006'::uuid, 'b0000026-0000-0000-0000-000000002803'::uuid, NULL, 'writing', 'fill_blank', 'Lengkapi frasa benda penjelas "kue yang dibuat ibu":', '{"sentence_template": "母が [blank] ケーキはおいしいです。", "translation": "Kue yang dibuat oleh ibu enak.", "options": ["作った", "作ります", "作って", "作ろう"]}'::jsonb, '{"selected": "作った"}'::jsonb, 'Klausul yang memodifikasi kata benda menggunakan bentuk biasa/kasual (tsukutta keeki).', 6, NOW()),
    ('c0000027-0000-0000-0000-280005000007'::uuid, 'b0000026-0000-0000-0000-000000002803'::uuid, NULL, 'listening', 'listening_choice', 'Dengarkan kalimat penjelas orang berikut:', '{"audio_text": "あそこで本を読んでいる人は誰ですか。", "options": [{"id": "opt_1", "text": "Siapakah orang yang sedang membaca buku di sana itu?"}, {"id": "opt_2", "text": "Siapakah orang yang berdiri di dekat pintu?"}, {"id": "opt_3", "text": "Apakah kamu mengenal guru itu?"}, {"id": "opt_4", "text": "Buku apa yang sedang kamu baca?"}]}'::jsonb, '{"selected_id": "opt_1"}'::jsonb, 'あそこで本を読んでいる人 = orang yang sedang membaca buku di sebelah sana.', 7, NOW()),
